gqT(){return"\ucc38\uace0 \ubb38\ud5cc \ubaa9\ub85d \uac80\uc99d \uc911\u2026"},
qV(a){return"\ucc38\uace0 \ubb38\ud5cc \ubaa9\ub85d\uff08"+a+"\uac1c \ud56d\ubaa9\uff09\uc774 \uac10\uc9c0\ub418\uc5c8\uc73c\uba70 \uc544\uc9c1 \uac80\uc99d\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4"},
gqW(){return'AI \uc0dd\uc131 \ucf58\ud150\uce20\uc5d0\ub294 \uadf8\ub7f4\ub4ef\ud558\uc9c0\ub9cc \uc2e4\uc81c\ub85c\ub294 \uc874\uc7ac\ud558\uc9c0 \uc54a\ub294 \ucc38\uace0 \ubb38\ud5cc\uc774 \ud754\ud788 \ud3ec\ud568\ub429\ub2c8\ub2e4. "\uc124\uc815"\uc5d0\uc11c \ud558\uc774\ud37c\ub9c1\ud06c \uac80\uc99d\uc744 \uaed0\uc2b5\ub2c8\ub2e4. \ub2e4\uc2dc \ucf1c\uba74 \uc790\ub3d9\uc73c\ub85c \uac80\uc99d\ub418\uba70, \uc544\ub798 \ubc84\ud2bc\uc73c\ub85c \ud55c \ubc88\ub9cc \uac80\uc99d\ud560 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.'},
