gqq(){return"\uff08ESL \ubcf4\uc815 \uc801\uc6a9\ub428\uff09"},
qt(a,b,c){return"\ucd1d "+a+"\ubb38\uc7a5 \xb7 AI \uc758\uc2ec "+b+"\ubb38\uc7a5 \xb7 \uc0ac\ub78c "+c+"\ubb38\uc7a5"},
qu(a,b,c,d){return"PDF \uac00\ub3c5\uc131\uc744 \uc720\uc9c0\ud558\uae30 \uc704\ud574 \ucc98\uc74c "+a+"\ubb38\uc7a5\ub9cc \ud45c\uc2dc\ub429\ub2c8\ub2e4\uff08\ucd1d "+b+'\ubb38\uc7a5\uff09. \uc804\uccb4 \ub370\uc774\ud130\uac00 \ud544\uc694\ud558\uba74 "'+c+'" \ub610\ub294 "'+d+'"\uc744 \uc774\uc6a9\ud574 \uc8fc\uc138\uc694.'},
gqs(){return"\ubb38\uc7a5\uff08\uc77c\uce58\ud55c \ud328\ud134 \ud3ec\ud568\uff09"},
ni(a){return"\uc774 \ud14d\uc2a4\ud2b8\ub294 AI\uac00 \uc0dd\uc131\ud588\uc744 \uac00\ub2a5\uc131\uc774 \ub9e4\uc6b0 \ub192\uc2b5\ub2c8\ub2e4\uff08AI \ud655\ub960 "+a+"%\uff09"},
