nj(a){return"\uc774 \ud14d\uc2a4\ud2b8\ub294 \uc0ac\ub78c\uc774 \uc791\uc131\ud588\uc744 \uac00\ub2a5\uc131\uc774 \ub9e4\uc6b0 \ub192\uc2b5\ub2c8\ub2e4\uff08AI \ud655\ub960 "+a+"%\uff09"},
ns(a,b){return"\uc804\uccb4 AI \ud655\ub960\uc740 "+a+"%\ub85c, \uc124\uc815\ud55c AI \ud45c\uc2dc \uc784\uacc4\uac12 "+b+"%\uc5d0 \ub3c4\ub2ec\ud558\uc5ec \ubcf4\uace0\uc11c\uac00 \uc774 \ud14d\uc2a4\ud2b8\ub97c AI\ub85c \ud45c\uc2dc\ud569\ub2c8\ub2e4. \ucd5c\uc885 \uacb0\uc815\uc744 \ub0b4\ub9ac\uae30 \uc804\uc5d0 \ubb38\uc7a5 \ub2e8\uc704 \uc99d\uac70\uc640 \uc5d4\uc9c4 \uc774\uc720\ub97c \uac80\ud1a0\ud558\uc138\uc694."},
