gp7(){return"\ud1b5\uacc4 \ubd84\uc11d (25%)"},
gp8(){return"\ubb38\uccb4 \ubd84\uc11d (20%)"},
gp5(){return"\uc801\ub300\uc801 \ubc29\uc5b4 (15%)"},
gp6(){return"\ub9ac\ud3ec\ud2b8 LLM (\uc120\ud0dd)"},
