gpi(){return"4\uac1c \uc5d4\uc9c4 \ubcd1\ub82c \ucd94\ub860"},
gpk(){return"\uc2e4\uc2dc\uac04 \uc9c4\ud589\ub960"},
gpj(){return"ESL \uc791\ubb38 \ubcf4\uc815"},
gpl(){return"\uc5b8\uc81c\ub4e0\uc9c0 \uc911\uc9c0 \uac00\ub2a5"},
gpq(){return"AI \uac1c\uc694 \uac8c\uc774\uc9c0"},
gpr(){return"\ubb38\uc7a5 \ud788\ud2b8\ub9f5"},
gpo(){return"\ubb38\ud5cc \uac80\uc99d"},
gpp(){return"PDF / CSV / JSON / PNG \ub0b4\ubcf4\ub0b4\uae30"},
goz(){return"\ubaa8\ub378 \ub2e4\uc6b4\ub85c\ub4dc \ubc0f \uc870\uc815 \uac00\uc774\ub4dc\uff08\ucd08\ubcf4\uc790\uc6a9\uff09"},
goq(){return"\ubaa8\ub378 \uad00\ub9ac \ud654\uba74 \uc5f4\uae30"},
gop(){return'\ud648 \ud654\uba74\uc5d0\uc11c \ud1b1\ub2c8\ubc14\ud034 \uc544\uc774\ucf58\uc744 \ud0ed\ud558\uc5ec "\uc124\uc815"\uc73c\ub85c \uc774\ub3d9\ud55c \ud6c4, "AI \ubaa8\ub378 \uad00\ub9ac" \uc606\uc758 "\uc5f4\uae30"\ub97c \ud0ed\ud569\ub2c8\ub2e4.'},
gos(){return"\uae30\uae30 \uc131\ub2a5\uc5d0 \ub530\ub77c \ubaa8\ub378 \uc120\ud0dd"},
gor(){return"\ud654\uba74\uc740 \uc0ac\uc6a9 \uc911\uc778 \uae30\uae30 \uc131\ub2a5\uff08RAM, CPU \ucf54\uc5b4 \uc218\uff09\uc5d0 \ub530\ub77c \uc801\ud569\ud55c \ubaa8\ub378 \ub4f1\uae09\uc744 \uc790\ub3d9\uc73c\ub85c \uc81c\uc548\ud558\uba70, \uac01 \uc5ed\ud560\uff08\ub2e4\uad6d\uc5b4 \ubd84\ub958\uae30\uff0f\ud1b5\uacc4 \ubd84\uc11d\uff0f\uc801\ub300\uc801 \ubc29\uc5b4\uff0f\ub9ac\ud3ec\ud2b8 LLM\uff09\uc5d0 \uc0ac\uc6a9 \uac00\ub2a5\ud55c \ubaa8\ub4e0 \ubcc0\ud615\uc744 \ub098\uc5f4\ud569\ub2c8\ub2e4."},
gou(){return"\ub2e4\uc6b4\ub85c\ub4dc \ubc0f \uc801\uc6a9"},
got(){return'\uc6d0\ud558\ub294 \ubaa8\ub378 \uc606\uc758 "\ub2e4\uc6b4\ub85c\ub4dc"\ub97c \ud0ed\ud558\uace0 \uc644\ub8cc\ub420 \ub54c\uae4c\uc9c0 \uae30\ub2e4\ub9bd\ub2c8\ub2e4\u2014\ucc98\uc74c \ub2e4\uc6b4\ub85c\ub4dc\ud55c \ubaa8\ub378\uc740 \uc790\ub3d9\uc73c\ub85c \uc0ac\uc6a9 \uc911\uc73c\ub85c \uc124\uc815\ub429\ub2c8\ub2e4. \uc5ec\ub7ec \ubcc0\ud615\uc774 \uc124\uce58\ub418\uc5b4 \uc788\uc73c\uba74 "\uc0ac\uc6a9 \uc911\uc73c\ub85c \uc124\uc815"\uc73c\ub85c \uc5b8\uc81c\ub4e0\uc9c0 \uc804\ud658\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ud734\uc9c0\ud1b5 \uc544\uc774\ucf58\uc744 \ud0ed\ud558\uba74 \ud544\uc694 \uc5c6\ub294 \ubaa8\ub378\uc744 \uc0ad\uc81c\ud558\uc5ec \uacf5\uac04\uc744 \ud655\ubcf4\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.'},
gow(){return"\ubaa8\ub378 \uc5c5\ub370\uc774\ud2b8"},
gov(){return'\uc0c8 \ubc84\uc804\uc774 \uc81c\uacf5\ub418\uba74 "AI \ubaa8\ub378 \uad00\ub9ac"\uc640 \uc124\uc815 \ud1b1\ub2c8\ubc14\ud034 \uc544\uc774\ucf58\uc5d0 \uc54c\ub9bc \ubc30\uc9c0\uac00 \ud45c\uc2dc\ub429\ub2c8\ub2e4. \uc774 \ud654\uba74\uc73c\ub85c \ub3cc\uc544\uc624\uba74 \uc0c8 \ubc84\uc804\uc744 \ud655\uc778\ud558\uace0 \ub2e4\uc6b4\ub85c\ub4dc\ud558\uc5ec \uc5c5\ub370\uc774\ud2b8\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4\uff08\uc218\ub3d9\uc73c\ub85c \uc0ad\uc81c\ud558\uc9c0 \uc54a\ub294 \ud55c \uae30\uc874 \uc124\uce58\ub41c \ubc84\uc804\uc740 \uc720\uc9c0\ub429\ub2c8\ub2e4\uff09.'},
goy(){return"\uace0\uae09: \uc0ac\uc6a9\uc790 \uc9c0\uc815 \ubaa8\ub378 \uac00\uc838\uc624\uae30"},
gox(){return'\ub2e4\ub978 \uacf3\uc5d0\uc11c \uc774\ubbf8 \ud638\ud658\ub418\ub294 .onnx \ubaa8\ub378\uc744 \ud655\ubcf4\ud588\uac70\ub098 \uc9c1\uc811 \ubbf8\uc138 \uc870\uc815\ud55c \uacbd\uc6b0, "\uc124\uc815 \u2192 \uc0ac\uc6a9\uc790 \uc9c0\uc815 ONNX \ubaa8\ub378 \uac00\uc838\uc624\uae30 \ubc0f \ud14c\uc2a4\ud2b8"\ub97c \ud1b5\ud574 \uac00\uc838\uc62c \uc218 \uc788\uc2b5\ub2c8\ub2e4\u2014\ubaa8\ub378 \ud30c\uc77c, \ud574\ub2f9 Tokenizer \uc124\uc815\uff08\ub610\ub294 "\ud544\uc694 \uc5c6\uc74c" \uc120\ud0dd\uff09, AI \ud074\ub798\uc2a4 \uc778\ub371\uc2a4\ub97c \uc81c\uacf5\ud574\uc57c \ud569\ub2c8\ub2e4. \uac00\uc838\uc624\uae30 \uc804\uc5d0 \ub3d9\uc77c\ud55c \ud30c\uc77c\uc774 \uc774\ubbf8 \uac00\uc838\uc640\uc84c\ub294\uc9c0 \uc790\ub3d9\uc73c\ub85c \ud655\uc778\ud558\uc5ec \uc2e4\uc218\ub85c \uc911\ubcf5 \uc124\uce58\ub418\ub294 \uac83\uc744 \ubc29\uc9c0\ud569\ub2c8\ub2e4.'},
goo(){return"\uacf5\uc2dd \ubaa8\ub378 \ub2e4\uc6b4\ub85c\ub4dc \ub9c1\ud06c"},
gon(){return"\ud56d\ubaa9\uc744 \ud0ed\ud558\uba74 \uc2dc\uc2a4\ud15c \ube0c\ub77c\uc6b0\uc800\uc5d0\uc11c \ud574\ub2f9 \ubaa8\ub378\uc758 \uacf5\uc2dd \ud398\uc774\uc9c0\uac00 \uc5f4\ub9bd\ub2c8\ub2e4."},
gom(){return"\ub2e4\uad6d\uc5b4 AI \ubd84\ub958\uae30\uff08Transformer, \uac00\uc911\uce58 40%\uff09"},
gol(){return"\ud63c\ub780\ub3c4 \ud1b5\uacc4 \ubaa8\ub378\uff08Statistical, \uac00\uc911\uce58 25%\uff09"},
goi(){return"\uc801\ub300\uc801 \ud328\ub7ec\ud504\ub808\uc774\uc988 \uac10\uc9c0 \ubaa8\ub378\uff08Adversarial, \uac00\uc911\uce58 15%\uff09"},
